"""Sub-pipelines: the call op, which runs a top-level def with bound params."""

import re

from etl.errors import schema_error
from etl.fields import Field, Map
from etl.steps import Context, Op, register

NAME_RE = re.compile(r'[A-Za-z_][A-Za-z0-9_]*\Z')

class DefName(Field):
    """Name of a def: an identifier, case-sensitive and kept exactly as given."""

    def normalize(self, value, path):
        if not isinstance(value, str) or not NAME_RE.match(value):
            raise schema_error("'%s' must be an identifier" % self.key, path)
        return value

class ParamValue(Field):
    """A JSON scalar or an array (of anything but objects)."""

    def normalize(self, value, path):
        if not self.allowed(value):
            raise schema_error("'%s' values must be JSON scalars or arrays" % self.key, path)
        return value

    def allowed(self, v):
        if isinstance(v, list):
            return all(self.allowed(x) for x in v)
        return v is None or isinstance(v, (bool, int, float, str))

@register
class Call(Op):
    name = 'call'
    fields = (DefName('name'), Map('params', ParamValue('params'), required=False, default={}))

    def run(self, step, rows, ctx):
        sub = Context(ctx.defs, step['params'])
        return sub.run(ctx.defs[step['name']], rows)
